/* GENERAL CSS */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: Arial, sans-serif;
}

body {
    background: #f1f6fd;
    color: #102b58;
}

/* =========================
   IMAGE 4 - HOME PAGE
========================= */

.navbar {
    height: 70px;
    background: white;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 5%;
    box-shadow: 0 2px 10px #cdd9eb;
}

.logo {
    font-size: 23px;
    font-weight: bold;
    color: #073b80;
}

.nav-links {
    display: flex;
    align-items: center;
    gap: 35px;
}

.nav-links a {
    text-decoration: none;
    color: #102b58;
    font-weight: bold;
}

.nav-links a:hover {
    color: #0879d5;
}

.nav-links button {
    background: #075ac5;
    color: white;
    border: none;
    padding: 12px 28px;
    border-radius: 25px;
    cursor: pointer;
}

.hero {
    min-height: 570px;
    padding: 60px 5%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 40px;
    background: linear-gradient(90deg, rgba(2, 8, 20, .72) 0%, rgba(2, 8, 20, .42) 48%, rgba(2, 8, 20, .12) 100%), url("data:image/png;base64,");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;base64,") center / cover no-repeat;
}

.hero-content {
    max-width: 500px;
    color: #ffffff;
    text-shadow: 0 2px 16px rgba(0, 0, 0, .55);
}

.hero-content h1 { color: #ffffff; }
.hero-content h2 { color: #f4f7ff; }
.hero-content p { color: #dce7f5; }

.hero-content h1 {
    font-size: 48px;
    margin-bottom: 15px;
}

.hero-content h2 {
    font-size: 30px;
    line-height: 1.4;
    margin-bottom: 18px;
}

.hero-content p {
    font-size: 17px;
    line-height: 1.6;
}

.registration-box {
    background: white;
    width: 420px;
    padding: 30px;
    border-radius: 15px;
    box-shadow: 0 5px 25px #a9c7e9;
}

.registration-box h2 {
    text-align: center;
    margin-bottom: 28px;
    font-size: 23px;
}

.form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px 15px;
}

.form-grid label {
    display: block;
    font-weight: bold;
    margin-bottom: 8px;
    font-size: 14px;
}

.form-grid input,
.form-grid select {
    width: 100%;
    padding: 12px 10px;
    border: 1px solid #c5d7ef;
    border-radius: 6px;
    outline: none;
    background: white;
}

.form-grid input:focus,
.form-grid select:focus {
    border-color: #0879d5;
}

.start-btn {
    width: 100%;
    background: #075ac5;
    color: white;
    border: none;
    padding: 15px;
    margin-top: 25px;
    border-radius: 7px;
    font-size: 15px;
    font-weight: bold;
    cursor: pointer;
}

.start-btn:hover {
    background: #03448f;
}


/* Camera and folder access buttons below Get Started */
.media-access-buttons { display: flex; gap: 12px; margin-top: 12px; }
.media-access-btn { flex: 1; background: #eaf2ff; color: #075ac5; border: 1px solid #9bbce8; padding: 12px 10px; border-radius: 7px; font-size: 14px; font-weight: bold; cursor: pointer; transition: background 0.2s ease; }
.media-access-btn:hover { background: #d8e8ff; }
.media-access-status { margin-top: 9px; color: #45617f; font-size: 12px; line-height: 1.4; overflow-wrap: anywhere; }
.hidden-file-input { display: none; }

footer {
    background: white;
    text-align: center;
    padding: 22px;
    color: #647b9d;
    font-size: 13px;
}


/* =========================
   IMAGE 1 - DASHBOARD
========================= */

#dashboardPage {
    display: none;
    min-height: 100vh;
    background: #f3f7fc;
}

.sidebar {
    width: 200px;
    background: linear-gradient(180deg, #073c78, #062c59);
    color: white;
    padding: 25px 12px;
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
}

.sidebar h2 {
    font-size: 20px;
    text-align: center;
    margin-bottom: 40px;
}

.menu {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.menu button {
    padding: 14px 12px;
    border: none;
    border-radius: 8px;
    color: white;
    background: transparent;
    text-align: left;
    font-size: 14px;
    cursor: pointer;
}

.menu button:hover,
.menu button.active {
    background: #0878c9;
}

.sidebar-bottom {
    background: #104b82;
    text-align: center;
    padding: 25px 10px;
    border-radius: 10px;
    margin-top: auto;
}

.sidebar-bottom h3 {
    margin-top: 10px;
    font-size: 16px;
}

.sidebar-bottom p {
    margin-top: 7px;
    font-size: 13px;
}

.main-content {
    flex: 1;
    min-width: 0;
    padding: 20px;
}

.topbar {
    height: 50px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 15px;
}


.topbar-left {
    display: flex;
    align-items: center;
    gap: 16px;
}

.back-registration-btn {
    background: #075ac5;
    color: #fff;
    border: none;
    padding: 10px 16px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: bold;
    cursor: pointer;
    transition: background 0.2s ease, transform 0.2s ease;
}

.back-registration-btn:hover {
    background: #06479c;
    transform: translateY(-1px);
}

.topbar h3 {
    font-size: 18px;
}

.user-menu {
    position: relative;
    display: inline-block;
}

.user-menu-toggle {
    display: flex;
    align-items: center;
    gap: 8px;
    background: transparent;
    color: inherit;
    border: 0;
    padding: 8px 10px;
    border-radius: 8px;
    font: inherit;
    cursor: pointer;
}

.user-menu-toggle:hover,
.user-menu-toggle[aria-expanded="true"] {
    background: rgba(7, 90, 197, 0.10);
}

.user-menu-arrow {
    font-size: 13px;
    transition: transform 0.2s ease;
}

.user-menu-toggle[aria-expanded="true"] .user-menu-arrow {
    transform: rotate(180deg);
}

.user-dropdown {
    display: none;
    position: absolute;
    top: calc(100% + 8px);
    right: 0;
    min-width: 205px;
    padding: 7px;
    background: #fff;
    border: 1px solid #dce5f0;
    border-radius: 10px;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.16);
    z-index: 1000;
}

.user-dropdown.show {
    display: block;
}

.user-dropdown button {
    display: block;
    width: 100%;
    padding: 11px 12px;
    text-align: left;
    color: #17324d;
    background: transparent;
    border: 0;
    border-radius: 7px;
    font-size: 14px;
    cursor: pointer;
}

.user-dropdown button:hover {
    background: #edf5ff;
}

.welcome-banner {
    min-height: 140px;
    background: linear-gradient(110deg, #073c78, #058bd5);
    border-radius: 12px;
    padding: 25px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: white;
    margin-bottom: 15px;
}

.welcome-banner h1 {
    font-size: 27px;
    margin-bottom: 12px;
}

.welcome-banner h3 {
    font-size: 16px;
    margin-bottom: 10px;
}

.welcome-banner p {
    font-size: 14px;
}

.heart-image {
    font-size: 75px;
    padding-right: 20px;
}

.stats-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px;
    margin-bottom: 15px;
}

.stat-card {
    background: white;
    padding: 20px;
    border-radius: 10px;
    box-shadow: 0 2px 10px #e0e9f5;
}

.stat-icon {
    font-size: 30px;
    display: block;
    margin-bottom: 8px;
}

.red {
    color: #f05262;
}

.blue {
    color: #16a7d1;
}

.green {
    color: #16ad82;
}

.green-text {
    color: #16a779;
}

.stat-card h2 {
    font-size: 24px;
    margin-bottom: 7px;
}

.stat-card p {
    color: #536985;
    font-size: 13px;
}

.bottom-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 15px;
}

.chart-card,
.quick-card,
.content-card {
    background: white;
    border-radius: 10px;
    padding: 22px;
    box-shadow: 0 2px 10px #e0e9f5;
}

.chart-card h3,
.quick-card h3 {
    margin-bottom: 20px;
}

.chart {
    height: 170px;
    display: flex;
    gap: 10px;
}

.chart-labels {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    font-size: 11px;
    color: #536985;
}

.chart svg {
    width: 100%;
    height: 100%;
    overflow: visible;
}

.chart line {
    stroke: #dce7f3;
    stroke-width: 1;
}

.line-one,
.line-two {
    fill: none;
    stroke-width: 3;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.line-one {
    stroke: #078bd8;
}

.line-two {
    stroke: #23b8ca;
}

.days {
    display: flex;
    justify-content: space-around;
    margin-left: 25px;
    margin-top: 8px;
    font-size: 11px;
    color: #536985;
}

.quick-card {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.quick-card button {
    padding: 13px;
    border: 1px solid #1685d1;
    color: #0757a4;
    background: white;
    border-radius: 6px;
    cursor: pointer;
    text-align: left;
}

.quick-card button:first-of-type {
    background: #0878c9;
    color: white;
}

.quick-card button:hover {
    background: #e5f3ff;
    color: #0757a4;
}


/* OTHER DASHBOARD PAGES */

.page-section {
    width: 100%;
}

.content-card {
    min-height: 300px;
    line-height: 1.8;
}

.content-card h2 {
    margin-bottom: 15px;
}

.content-card p {
    margin-bottom: 12px;
}

.risk-circle {
    width: 150px;
    height: 150px;
    border: 12px solid #0796d4;
    border-left-color: #dce7f3;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 32px;
    font-weight: bold;
    margin: 30px auto;
}

.tip {
    background: #f0f6ff;
    border-radius: 8px;
    padding: 15px;
    margin-top: 15px;
}

.tip h3 {
    color: #0757a4;
}


/* RESPONSIVE DESIGN */

@media(max-width: 850px) {

    .hero {
        flex-direction: column;
        align-items: stretch;
    }

    .registration-box {
        width: 100%;
    }

    .stats-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .bottom-grid {
        grid-template-columns: 1fr;
    }

    .sidebar {
        width: 160px;
    }
}

@media(max-width: 550px) {
    .hero {
        background-position: 58% center;
        padding: 42px 5%;
    }


    .navbar {
        padding: 15px;
        height: auto;
        flex-direction: column;
        gap: 15px;
    }

    .nav-links {
        gap: 12px;
        flex-wrap: wrap;
        justify-content: center;
    }

    .nav-links a {
        font-size: 12px;
    }

    .hero-content h1 {
        font-size: 35px;
    }

    .form-grid {
        grid-template-columns: 1fr;
    }

    #dashboardPage {
        flex-direction: column;
    }

    .sidebar {
        width: 100%;
    }

    .sidebar h2 {
        margin-bottom: 15px;
    }

    .menu {
        flex-direction: row;
        flex-wrap: wrap;
    }

    .menu button {
        font-size: 12px;
    }

    .sidebar-bottom {
        display: none;
    }

    .main-content {
        padding: 12px;
    }

    .stats-grid {
        grid-template-columns: 1fr 1fr;
    }

    .welcome-banner h1 {
        font-size: 21px;
    }

    .heart-image {
        font-size: 45px;
    }
}


/* DATASET-BASED ASSESSMENT ADDITIONS */
.form-grid .full-width { grid-column: 1 / -1; }
.form-grid input, .form-grid select { min-height: 44px; }
.form-note { font-size: 12px; color: #647b9d; line-height: 1.5; margin-top: 14px; }
.risk-result { margin: 22px auto; max-width: 620px; text-align: center; padding: 22px; background: #f0f7ff; border-radius: 12px; }
.risk-score { font-size: 42px; font-weight: bold; color: #075ac5; margin: 12px 0; }
.risk-meter { height: 12px; background: #dce7f3; border-radius: 20px; overflow: hidden; margin: 12px 0; }
.risk-meter-fill { height: 100%; width: 0%; background: #0879d5; transition: width .4s ease; }
.dataset-note { background: #eef6ff; border-left: 4px solid #0879d5; padding: 14px; border-radius: 7px; margin-top: 18px; font-size: 13px; }
.stat-card small { color: #7a8da8; display: block; margin-top: 5px; font-size: 11px; }
@media(max-width: 550px) {
  .form-grid .full-width { grid-column: auto; }
}


/* DAY 2: calculators and biomarker cards */
.calculator-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:18px; margin:18px 0; }
.calculator-card { background:#fff; border-radius:12px; padding:22px; box-shadow:0 2px 10px #e0e9f5; }
.calculator-card h3 { margin-bottom:8px; color:#073b80; }
.calculator-card p { color:#647b9d; font-size:13px; margin-bottom:16px; }
.calculator-fields { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
.calculator-fields label { display:block; font-weight:bold; font-size:13px; margin-bottom:6px; }
.calculator-fields input { width:100%; padding:12px; border:1px solid #c5d7ef; border-radius:7px; min-height:44px; }
.calculator-fields input:focus { outline:2px solid #a7d3ff; border-color:#0879d5; }
.calc-btn { margin-top:15px; padding:12px 18px; border:0; border-radius:7px; background:#075ac5; color:#fff; font-weight:bold; cursor:pointer; }
.calc-btn:hover { background:#03448f; }
.calc-result { display:none; margin-top:16px; padding:15px; border-radius:9px; background:#f0f7ff; line-height:1.6; }
.calc-result.visible { display:block; }
.calc-result strong { color:#073b80; }
.biomarker-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:14px; margin:18px 0 22px; }
.biomarker-card { background:#fff; padding:17px; border-radius:10px; box-shadow:0 2px 10px #e0e9f5; border-top:4px solid #8aa6c8; min-width:0; }
.biomarker-card h3 { font-size:14px; color:#536985; margin-bottom:10px; }
.biomarker-value { font-size:22px; font-weight:bold; color:#073b80; overflow-wrap:anywhere; }
.biomarker-status { display:inline-block; margin-top:9px; padding:5px 9px; border-radius:20px; font-size:11px; font-weight:bold; background:#edf2f8; color:#536985; }
.status-good { background:#e5f7ed; color:#147847; }
.status-warn { background:#fff3d6; color:#8a5b00; }
.status-high { background:#ffe7e7; color:#a32222; }
.status-info { background:#e7f2ff; color:#0757a4; }
.section-subtitle { color:#647b9d; font-size:13px; margin:-7px 0 12px; }
.health-reference { font-size:12px; color:#647b9d; margin-top:14px; line-height:1.5; }
@media(max-width:850px) { .biomarker-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media(max-width:550px) {
 .calculator-grid { grid-template-columns:1fr; }
 .calculator-fields { grid-template-columns:1fr; }
 .biomarker-grid { grid-template-columns:1fr 1fr; }
}


/* DAY 3: PATIENT RISK REPORT */
.report-actions { display:flex; flex-wrap:wrap; gap:12px; margin:22px 0; }
.report-btn { border:0; border-radius:8px; padding:12px 18px; color:#fff; background:#075ac5; font-weight:700; cursor:pointer; }
.report-btn.secondary { background:#17456f; }
.report-sheet { background:#fff; border:1px solid #d8e3f1; border-radius:12px; padding:28px; margin-top:18px; color:#183354; }
.report-header { display:flex; justify-content:space-between; gap:16px; align-items:flex-start; border-bottom:2px solid #dce8f6; padding-bottom:16px; margin-bottom:18px; }
.report-header h2 { color:#073b80; margin-bottom:6px; }
.report-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; margin:14px 0 20px; }
.report-item { background:#f4f8fd; border-radius:8px; padding:12px; overflow-wrap:anywhere; }
.report-item strong { display:block; font-size:12px; color:#607895; margin-bottom:5px; }
.report-sheet h3 { color:#073b80; margin:20px 0 9px; }
.report-sheet p, .report-sheet li { line-height:1.55; font-size:14px; }
.report-sheet ul { padding-left:20px; }
.report-disclaimer { background:#fff8e8; border-left:4px solid #d99b25; padding:13px; margin-top:18px; }
.report-muted { color:#647b9d; font-size:12px !important; }
@media (max-width:650px) {
  .report-header { display:block; }
  .report-grid { grid-template-columns:1fr; }
  .report-sheet { padding:17px; }
}
@media print {
  body * { visibility:hidden !important; }
  #printableReport, #printableReport * { visibility:visible !important; }
  #printableReport { position:absolute !important; left:0 !important; top:0 !important; width:100% !important; margin:0 !important; padding:18px !important; border:0 !important; box-shadow:none !important; }
  .report-actions, .no-print { display:none !important; }
  @page { size:A4; margin:14mm; }
}



/* RESPONSIVE PATIENT REGISTRATION FORM - DESKTOP, TABLET AND MOBILE */
.hero {
    width: 100%;
    align-items: center;
    gap: clamp(24px, 4vw, 56px);
    padding: clamp(28px, 4vw, 60px) clamp(18px, 5vw, 5%);
}

.hero-content {
    flex: 0.85 1 320px;
    min-width: 0;
}

.registration-box {
    flex: 1.15 1 560px;
    width: auto;
    max-width: 760px;
    min-width: 0;
    padding: clamp(22px, 3vw, 38px);
}

.form-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18px 20px;
}

.form-grid > div { min-width: 0; }
.form-grid input,
.form-grid select {
    min-width: 0;
    min-height: 48px;
    padding: 12px 13px;
    font-size: 16px; /* avoids automatic zoom on iOS */
}

.form-grid label {
    line-height: 1.35;
}

.start-btn {
    min-height: 50px;
    font-size: 16px;
}

@media (max-width: 850px) {
    .hero {
        flex-direction: column;
        align-items: stretch;
        justify-content: flex-start;
        gap: 28px;
        padding: 34px 5%;
    }
    .hero-content,
    .registration-box {
        flex: none;
        width: 100%;
        max-width: 100%;
    }
    .hero-content { max-width: 680px; }
}

@media (max-width: 550px) {
    .hero { padding: 26px 14px; gap: 22px; }
    .hero-content h1 { font-size: clamp(30px, 9vw, 36px); }
    .hero-content h2 { font-size: 25px; }
    .hero-content p { font-size: 15px; }
    .registration-box {
        padding: 21px 16px;
        border-radius: 13px;
    }
    .registration-box h2 { font-size: 21px; margin-bottom: 22px; }
    .form-grid { grid-template-columns: minmax(0, 1fr); gap: 15px; }
    .form-grid .full-width { grid-column: auto; }
    .form-grid input,
    .form-grid select { width: 100%; min-height: 48px; }
    .form-note { font-size: 12px; }
}


/* Patient registration: keep labels and entered details clearly readable in black */
.registration-box .form-grid label {
    color: #000000;
}
.registration-box .form-grid input,
.registration-box .form-grid select,
.registration-box .form-grid textarea {
    color: #000000;
    -webkit-text-fill-color: #000000;
}
.registration-box .form-grid input::placeholder,
.registration-box .form-grid textarea::placeholder {
    color: #666666;
    opacity: 1;
}


/* STANDALONE ABOUT AND HEALTH TIPS PAGES */
#standaloneInfoPage {
    display: none;
    min-height: 100vh;
    padding: 28px 5%;
    background: #f1f6fd;
    color: #102b58;
}
.standalone-info-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    max-width: 1100px;
    margin: 0 auto 24px;
    padding: 16px 20px;
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 2px 10px #cdd9eb;
}
.standalone-info-header h1 { font-size: 22px; color: #073b80; }
.standalone-back-btn {
    border: 0; border-radius: 8px; padding: 11px 17px;
    background: #075ac5; color: white; font-weight: bold; cursor: pointer;
}
.standalone-back-btn:hover { background: #06479c; }
#standaloneInfoContent { max-width: 1100px; margin: 0 auto; }
#standaloneInfoContent .content-card { width: 100%; margin: 0; }
@media(max-width:600px) {
    #standaloneInfoPage { padding: 16px 12px; }
    .standalone-info-header { align-items: flex-start; flex-direction: column; }
}


/* Refined clinical dashboard navigation */
.sidebar {
    width: 252px;
    background: linear-gradient(165deg, #102f50 0%, #0b2440 55%, #102f50 100%);
    padding: 28px 16px 18px;
    border-right: 1px solid rgba(255,255,255,.08);
}
.sidebar-brand {
    display:flex; align-items:center; gap:12px;
    padding: 5px 10px 28px; margin-bottom: 22px;
    border-bottom:1px solid rgba(255,255,255,.13);
}
.brand-mark {
    width:42px;height:42px;border-radius:14px;
    display:grid;place-items:center;background:#e8f7f6;color:#087f83;
    font-size:25px;font-weight:800;box-shadow:0 5px 16px rgba(0,0,0,.16);
}
.sidebar-brand strong {display:block;font-size:19px;letter-spacing:-.4px;color:#fff;}
.sidebar-brand small {display:block;margin-top:4px;font-size:9px;letter-spacing:2px;color:#9bb8ca;font-weight:700;}
.menu {gap:8px;}
