    .menu button {padding:8px;min-height:45px;font-size:12px;gap:8px;}
    .menu button .nav-icon {width:28px;height:28px;flex-basis:28px;}
    .sidebar-bottom {display:none;}
}


/* Animated notification bell */
.notification-bell {
    position: relative; display: inline-flex; align-items: center; justify-content: center;
    width: 40px; height: 40px; margin-right: 7px; border: 1px solid #d9e9ee;
    border-radius: 12px; background: #f0fbfb; color: #087f83; cursor: pointer;
    transition: background .2s ease, transform .2s ease, box-shadow .2s ease;
}
.notification-bell:hover { background: #ddf5f2; transform: translateY(-2px); box-shadow: 0 5px 14px rgba(8,127,131,.16); }
.notification-bell svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transform-origin: 50% 15%; }
.notification-bell.is-ringing svg { animation: medicalBellRing .75s ease-in-out; }
.notification-bell.is-ringing { box-shadow: 0 0 0 5px rgba(8,127,131,.12); }
.bell-dot { position: absolute; top: 7px; right: 7px; width: 7px; height: 7px; border: 1.5px solid #f0fbfb; border-radius: 50%; background: #ef6b68; }
@keyframes medicalBellRing { 0%,100% { transform: rotate(0); } 15%,45%,75% { transform: rotate(14deg); } 30%,60%,90% { transform: rotate(-14deg); } }
@media (prefers-reduced-motion: reduce) { .notification-bell.is-ringing svg { animation: none; } }

/* Notification dropdown panel */
.notification-panel {
    display: none; position: absolute; top: calc(100% + 12px); right: 48px;
    width: min(360px, calc(100vw - 28px)); max-height: 420px; overflow: hidden;
    background: #fff; color: #203449; border: 1px solid #dce8ee; border-radius: 16px;
    box-shadow: 0 18px 45px rgba(13, 39, 61, .20); z-index: 1000;
}
.notification-panel.is-open { display: block; animation: notificationPanelIn .18s ease-out; }
@keyframes notificationPanelIn { from { opacity: 0; transform: translateY(-7px); } to { opacity: 1; transform: translateY(0); } }
.notification-panel-head { display:flex; align-items:center; justify-content:space-between; gap:12px; padding:16px 17px 12px; border-bottom:1px solid #edf2f5; }
.notification-panel-head h3 { margin:0; font-size:16px; color:#17364b; }
.notification-count { font-size:11px; font-weight:700; color:#087f83; background:#e8f7f5; border-radius:20px; padding:5px 9px; }
.notification-actions { display:flex; justify-content:space-between; align-items:center; padding:9px 16px; background:#f8fbfc; }
.notification-actions button { border:0; background:transparent; color:#087f83; font-size:11px; font-weight:700; cursor:pointer; padding:4px 0; }
.notification-list { max-height:285px; overflow-y:auto; }
.notification-item { display:flex; gap:11px; padding:13px 16px; border-bottom:1px solid #f0f3f5; cursor:pointer; transition:background .15s; }
.notification-item:hover { background:#f7fbfb; }
.notification-item.unread { background:#f0faf9; }
.notification-item:last-child { border-bottom:0; }
.notification-symbol { flex:0 0 34px; width:34px; height:34px; display:grid; place-items:center; border-radius:11px; background:#e5f5f3; color:#087f83; font-size:16px; }
.notification-copy { min-width:0; flex:1; }
.notification-copy strong { display:block; font-size:12px; color:#1e3a50; margin:1px 0 4px; }
.notification-copy p { margin:0; color:#617487; font-size:11px; line-height:1.45; }
.notification-copy time { display:block; color:#91a0ad; font-size:10px; margin-top:5px; }
.notification-unread-dot { width:7px; height:7px; flex:0 0 7px; border-radius:50%; background:#0c9b91; margin-top:5px; }
.notification-empty { padding:28px 18px; text-align:center; color:#718394; font-size:12px; }
@media(max-width:520px) {
    .notification-panel { right: -4px; top: calc(100% + 10px); width:min(340px, calc(100vw - 24px)); }
}


